import{_ as a,C as i,o,c as n,a3 as t,E as r}from"./chunks/framework.uTHcANy5.js";const v=JSON.parse('{"title":"Editing","description":"","frontmatter":{},"headers":[],"relativePath":"tools/edit.md","filePath":"tools/edit.md"}'),d={name:"tools/edit.md"};function h(l,e,p,c,g,k){const s=i("MosaicEditTogether");return o(),n("div",null,[e[0]||(e[0]=t('<h1 id="editing" tabindex="-1">Editing <a class="header-anchor" href="#editing" aria-label="Permalink to &quot;Editing&quot;">​</a></h1><p><code>mosaic edit</code> opens a model in your browser so you can change it, then saves it as a <code>.tsr</code> or composes it into a <code>.glb</code>, wherever you choose:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">model.glb</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> model.gltf</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> model.tsr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; [--port </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--no-open]</span></span></code></pre></div><p>A glTF model is converted to Mosaic first, with <a href="/mosaic/dist/docs/tools/gltf">stable ids</a>, so editing the same model twice names its nodes the same way. A <code>.tsr</code> opens as it is.</p><h2 id="the-editor" tabindex="-1">The editor <a class="header-anchor" href="#the-editor" aria-label="Permalink to &quot;The editor&quot;">​</a></h2><p>The page is the <a href="/mosaic/dist/docs/examples/">viewer</a>, holding just your model: the node tree, the 3D view and the components of whatever node you select.</p><h3 id="moving-parts-in-3d" tabindex="-1">Moving parts in 3D <a class="header-anchor" href="#moving-parts-in-3d" aria-label="Permalink to &quot;Moving parts in 3D&quot;">​</a></h3><p>Click a part of the model to select it. It&#39;s tinted, outlined with a box (visible through whatever is in front of it), highlighted in the tree, and a handle appears at its centre. Drag the handle to move the part, and everything under it moves along.</p><table tabindex="0"><thead><tr><th>Key</th><th>Does</th></tr></thead><tbody><tr><td><strong>W</strong></td><td>move</td></tr><tr><td><strong>E</strong></td><td>rotate</td></tr><tr><td><strong>R</strong></td><td>scale</td></tr><tr><td><strong>↑</strong></td><td>select the part&#39;s parent: a click picks the smallest part under the mouse, like one bolt rather than the wheel</td></tr><tr><td><strong>Esc</strong></td><td>deselect; so does clicking empty space</td></tr></tbody></table><p>Selecting a node in the tree puts the handle on it too. When you let go, the node&#39;s new position, relative to its parent, is written to its <code>core::transform</code>. Every move is a section of its own at the end of the archive, written by &quot;mosaic edit&quot;, so the moves stay a clear layer on top of the original.</p><h3 id="editing-together" tabindex="-1">Editing together <a class="header-anchor" href="#editing-together" aria-label="Permalink to &quot;Editing together&quot;">​</a></h3><p>Open the editor&#39;s address in a second tab, and the two tabs edit the same model together. A part moved in one tab moves in the other when you let go. There&#39;s no server in between: tabs of one browser on the same page talk to each other directly.</p><p>Try it here: these are two editors on a car. Click a part in one, such as a wheel or a door, drag the handle, and let go. The same part moves in the other editor, and only that part: the other editor moves what it already drew instead of drawing the car again.</p>',13)),r(s,{example:"ferrari",height:"400",credit:"Model: www.vecarz.com"}),e[1]||(e[1]=t(`<p>Any viewer link can edit like this: add <code>&amp;edit</code> to it, as in <code>viewer/?example=ferrari&amp;edit</code>. Viewers with the same <code>&amp;channel=&lt;name&gt;</code> share their moves; without one, every viewer editing that example in your browser does. Nothing is saved there: reloading starts from the example again.</p><ul><li><strong>Each tab has a name</strong>, such as <code>tab-3f2a</code>, shown in the status line and the tab&#39;s title. Its moves are sections with that name as their author, so a saved <code>.tsr</code> says who moved what.</li><li><strong>A tab opened later catches up.</strong> It asks the open tabs for everything done so far and applies it. If every tab is closed, the shared moves are gone; save first.</li><li><strong>If two tabs move the same part, the later move wins</strong>, in every tab. &quot;Later&quot; means made after seeing the other one, not by the clock on the wall. Every tab keeps the edit sections in that order, however they arrived, so all tabs end up with the same archive.</li><li><strong>The header counts what was edited</strong>, such as <code>12 edits · 9.8 KB</code>: the edits made by every editor, and the size of all of them as they were sent, added up. Hover over it to see how much they take up once they&#39;re inside the archive.</li><li><strong>Only moves are shared.</strong> Typing in the Files drawer stays in the tab where you typed it.</li></ul><p>Under the hood, every move travels as a <strong><code>.tsr</code> of one section</strong>: an archive like any other, which <code>mosaic diff</code>, <code>mosaic federate</code> or the viewer could open. The section header says who made it and when; its place in the order of edits, a counter that goes up with every edit seen, is in the header&#39;s <code>dataVersion</code>. The rows it sets are in the archive&#39;s tables, under the reference ids the node already uses, so the edit replaces the node&#39;s old transform rather than adding a second one. Each editor adds the edit to its archive as one more section. Because an edit is already a Mosaic archive, the same edits can later travel through the <a href="/mosaic/dist/docs/sdk/http-api">HTTP API</a>, each published as a version, without changing anything but how they&#39;re carried.</p><h3 id="editing-the-files" tabindex="-1">Editing the files <a class="header-anchor" href="#editing-the-files" aria-label="Permalink to &quot;Editing the files&quot;">​</a></h3><p>The <strong>Files</strong> drawer underneath shows the archive as it really is: an <code>index.json</code> naming the nodes and their components, and one <code>.ndjson</code> table per component type, one value per line.</p><ol><li>Pick a file in the drawer, for example <code>khronos::gltf::material.ndjson</code>, and change it.</li><li>Press <strong>Save</strong> in the drawer. The model is rebuilt from your edit and drawn again.</li></ol><p>Moves you make in 3D show up in the drawer straight away. If the drawer has unsaved typing when you move something, it isn&#39;t refreshed; press <strong>Revert</strong> there before saving, or it would put the old transform back.</p><h3 id="writing-it-to-disk" tabindex="-1">Writing it to disk <a class="header-anchor" href="#writing-it-to-disk" aria-label="Permalink to &quot;Writing it to disk&quot;">​</a></h3><p>When you&#39;re happy, press one of the two buttons in the header. Each asks where to save:</p><table tabindex="0"><thead><tr><th>Button</th><th>Saves</th><th>Suggested name</th></tr></thead><tbody><tr><td><strong>Save .tsr</strong></td><td>the edited archive</td><td><code>&lt;model&gt;.tsr</code></td></tr><tr><td><strong>Export .glb</strong></td><td>the edited archive, composed</td><td><code>&lt;model&gt;.edited.glb</code></td></tr></tbody></table><p>In Chrome and Edge this is the browser&#39;s save dialog, so you pick the folder and name. Firefox and Safari don&#39;t offer that dialog, so the file is downloaded instead; it asks where only if your browser is set to ask for downloads.</p><p>The buttons save your moves and what you last saved in the drawer. If the drawer still holds unsaved typing, they say so instead of saving. Reloading the page brings back what was last saved.</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-1" id="tab-1-1" checked><label data-title="glb" for="tab-1-1">glb</label><input type="radio" name="group-1" id="tab-1-2"><label data-title="tsr" for="tab-1-2">tsr</label><input type="radio" name="group-1" id="tab-1-3"><label data-title="what changed" for="tab-1-3">what changed</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> car.glb</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save .tsr    -&gt; asks, suggesting car.tsr</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export .glb  -&gt; asks, suggesting car.edited.glb</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> edit</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scene.tsr</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Save .tsr    -&gt; asks, suggesting scene.tsr</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Export .glb  -&gt; asks, suggesting scene.edited.glb</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> car.glb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> original.tsr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stable-ids</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mosaic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> diff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> original.tsr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> car.tsr</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # only your edits</span></span></code></pre></div></div></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>The page needs internet</strong> for three.js and the code editor, which load from a CDN. Your model never leaves your machine: the server listens on <code>127.0.0.1</code> only, and it writes nothing to disk itself. Files go only where you save them.</li><li><strong>A part placed more than once</strong> (the same node under several parents) is one node with one transform, so moving it moves every copy. Clicking such a part in 3D selects the nearest part above it that is placed only once, which is usually what you meant by pointing at one copy. To move every copy, select the part in the tree.</li><li><strong>Editing together needs the tabs in one browser</strong>, on the same address. Two machines, or two browsers, don&#39;t see each other&#39;s moves.</li><li><strong>There&#39;s no undo yet.</strong> Move it back, or reload the page to return to what was last written.</li><li><strong>Imports aren&#39;t followed.</strong> A <code>.tsr</code> that imports others opens on its own, showing only what it holds itself.</li><li><strong>Large models are fine to view, slow to edit as text.</strong> A converted model keeps its geometry and textures in <code>khronos::gltf::buffer.ndjson</code> as long base64 lines. Open the smaller tables (materials, transforms, names in <code>index.json</code>) to make changes.</li><li><code>--port</code> picks the port, otherwise a free one is used. <code>--no-open</code> prints the address instead of opening a browser.</li></ul>`,15))])}const y=a(d,[["render",h]]);export{v as __pageData,y as default};
